import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Color
  } = THREE;

  const root = new Group();
  root.name = config.id || 'journal-card-3';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const timelines = [];
  const primitiveCleanups = [];
  const resources = [];
  let disposed = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropV = uv().y;
  const lowerGradient = mix(
    vec3(colors.surface),
    vec3(colors.ink),
    smoothstep(0.0, 0.52, backdropV)
  );
  backdropMaterial.colorNode = mix(
    lowerGradient,
    vec3(colors.ink),
    smoothstep(0.52, 1.0, backdropV)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'journal-card-3-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const cardGroup = new Group();
  cardGroup.name = 'journal-card-3-surface';
  cardGroup.position.set(0, -0.4, 0.08);
  root.add(cardGroup);

  const cardGeometry = new PlaneGeometry(2.55, 1.62);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.paper)
  });
  cardMaterial.color.set(colors.paper);

  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'journal-card-3-image';
  cardGroup.add(card);
  resources.push(cardGeometry, cardMaterial);

  const surfaceGeometry = new PlaneGeometry(2.55, 1.62);
  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.42
  });
  const surface = new Mesh(surfaceGeometry, surfaceMaterial);
  surface.name = 'journal-card-3-surface-tint';
  surface.position.z = 0.012;
  cardGroup.add(surface);
  resources.push(surfaceGeometry, surfaceMaterial);

  const edgeGeometry = new BoxGeometry(0.045, 1.62, 0.035);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.accent)
  });
  const accentEdge = new Mesh(edgeGeometry, edgeMaterial);
  accentEdge.name = 'journal-card-3-accent-edge';
  accentEdge.position.set(-1.255, 0, 0.035);
  accentEdge.visible = false;
  cardGroup.add(accentEdge);
  resources.push(edgeGeometry, edgeMaterial);

  const topAccentGeometry = new BoxGeometry(0.34, 0.045, 0.035);
  const topAccent = new Mesh(topAccentGeometry, edgeMaterial);
  topAccent.name = 'journal-card-3-foreground-accent';
  topAccent.position.set(0.92, 0.79, 0.04);
  cardGroup.add(topAccent);
  resources.push(topAccentGeometry);

  let textOffset = -0.9;
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: item.role === 'headline' ? colors.paper : colors.ink,
      align: 'left',
      letterSpacingPx: item.role === 'label' ? 3 : 0
    });

    textObject.name = `journal-card-3-text-${item.role || 'content'}`;
    textObject.position.set(textOffset, -0.48, 0.055);
    cardGroup.add(textObject);
    textOffset += 0.08;
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      cardMaterial.map = texture;
      cardMaterial.color.set('#ffffff');
      cardMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  const intro = gsap.timeline();
  intro.set(cardGroup.scale, { x: 1.04, y: 1.04, z: 1.04 });
  intro.to(cardGroup.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);
  intro.to(cardGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, 0);
  timelines.push(intro);

  let hoverTween;
  let pressTween;

  const handlers = {
    hover: (active = true) => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(cardGroup.position, {
        y: active ? 0.15 : 0,
        duration: 0.3,
        ease: 'power2.out'
      });
      timelines.push(hoverTween);
    },

    click: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.timeline();
      pressTween.to(cardGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      });
      pressTween.to(cardGroup.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.42,
        ease: 'back.out(2)'
      });
      timelines.push(pressTween);
      ctx.emit('hub-journal.select', {
        id: config.id || 'journal-card-3'
      });
    },

    focus: () => {
      accentEdge.visible = true;
    },

    blur: () => {
      accentEdge.visible = false;
    }
  };

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.userData.handlers = {};
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    if (result?.timeline) timelines.push(result.timeline);
  }

  return root;
}

export default createNode;
